param([Parameter(Mandatory=$true)][ValidateSet('PREPARE','INSTALL','ARM','RETRIEVE','VERIFY','UNINSTALL','POSTCHECK')][string]$Stage,[Parameter(Mandatory=$true)][string]$SessionDirectory,[string]$Serial,[ValidateSet('','M5_PERMISSION_ONLY')][string]$LiveAuthorization='')
$ErrorActionPreference='Stop';$root=Split-Path (Split-Path $PSScriptRoot -Parent) -Parent
$preflight=(& "$PSScriptRoot/Test-M5FrozenPreflight.ps1"|ConvertFrom-Json);$package=$preflight.package;$factory='com.honda.androidauto.projection.sink';$adb=$preflight.adb
if($Stage-eq'PREPARE'){
 if(Test-Path -LiteralPath $SessionDirectory){throw 'Fresh future session directory required'};New-Item -ItemType Directory -Path $SessionDirectory|Out-Null
 [ordered]@{phase='PREPARED';runId=('m5_'+[guid]::NewGuid().ToString('N'));apkSHA256=$preflight.sha256;serial=$null;phoneSwap='manual';next='INSTALL only after separately authorized car session';liveExecuted=$false}|ConvertTo-Json|Set-Content "$SessionDirectory/session.json"
 Write-Output 'OFFLINE PREPARED. No ADB used. Have phone unlocked, cable ready, USB mode navigation ready BEFORE ARM.';exit
}
if($LiveAuthorization-ne'M5_PERMISSION_ONLY'-or$Serial-ne'00000000'){throw 'REFUSED: explicit future M5-only authorization and recorded head-unit serial00000000 required; NO ADB invoked'}
$SessionDirectory=(Resolve-Path -LiteralPath $SessionDirectory).Path;$state=Get-Content "$SessionDirectory/session.json" -Raw|ConvertFrom-Json
if($state.apkSHA256-ne$preflight.sha256){throw 'Session artifact mismatch'}
function Save { $state|ConvertTo-Json -Depth 6|Set-Content "$SessionDirectory/session.json" }
function Adb([string[]]$Arguments,[switch]$AllowFailure){
 $stem=Join-Path $SessionDirectory ((Get-Date -Format 'yyyyMMdd-HHmmss-fff')+'-m5-adb-'+[guid]::NewGuid().ToString('N').Substring(0,8))
 $si=[Diagnostics.ProcessStartInfo]::new();$si.FileName=$adb;$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true
 foreach($a in (@('-s',$Serial)+$Arguments)){$si.ArgumentList.Add($a)}
 $p=[Diagnostics.Process]::new();$p.StartInfo=$si;$utc=[DateTime]::UtcNow.ToString('o');[void]$p.Start();$out=$p.StandardOutput.ReadToEndAsync();$err=$p.StandardError.ReadToEndAsync();$timeout=-not$p.WaitForExit(30000)
 if($timeout){$p.Kill();$p.WaitForExit()};$stdout=$out.GetAwaiter().GetResult();$stderr=$err.GetAwaiter().GetResult();$code=$p.ExitCode;$p.Dispose()
 [IO.File]::WriteAllText($stem+'.stdout.txt',$stdout);[IO.File]::WriteAllText($stem+'.stderr.txt',$stderr)
 $record=[ordered]@{utc=$utc;endUtc=[DateTime]::UtcNow.ToString('o');serial=$Serial;arguments=$Arguments;exit=$code;timedOut=$timeout;stdout=$stem+'.stdout.txt';stderr=$stem+'.stderr.txt'}
 $record|ConvertTo-Json -Depth 5|Set-Content ($stem+'.command.json');Add-Content "$SessionDirectory/commands.jsonl" ($record|ConvertTo-Json -Compress)
 if(($code-ne0-or$timeout)-and-not$AllowFailure){throw "M5 command failed (exit=$code timeout=$timeout): $($Arguments-join' '); raw outputs saved"};return $stdout
}
$fingerprint=Adb -Arguments @('shell','getprop','ro.build.fingerprint');$api=(Adb -Arguments @('shell','getprop','ro.build.version.sdk')).Trim()
if($api-ne'22'-or$fingerprint.Trim()-ne'Acura/gen1CBD_HS/gen1CBD_HS:5.1.1/LMY48P/14:user/release-keys'){throw 'Unexpected car identity/firmware: stop without installation or arming'}
if($state.serial-and$state.serial-ne$Serial){throw 'Session serial changed'};$state.serial=$Serial;Save
function Snapshot([string]$Name){
 $dir=Join-Path $SessionDirectory $Name;New-Item -ItemType Directory -Path $dir|Out-Null
 foreach($item in @(@('date','shell','date'),@('uptime','shell','cat','/proc/uptime'),@('usb','shell','dumpsys','usb'),@('display','shell','dumpsys','display'),@('window','shell','dumpsys','window'),@('wm-size','shell','wm','size'),@('honda-package','shell','dumpsys','package',$factory))){(Adb -Arguments $item[1..($item.Length-1)])|Set-Content "$dir/$($item[0]).txt"}
 $path=(Adb -Arguments @('shell','pm','path',$factory)).Trim();if($path-notmatch'^package:(/system/(app|priv-app)/[A-Za-z0-9_./-]+\.apk)$'){throw 'Factory path changed/split; manual read-only review required'};$remote=$Matches[1];$path|Set-Content "$dir/honda-path.txt";[void](Adb -Arguments @('pull',$remote,"$dir/factory-aa.apk"));Get-FileHash "$dir/factory-aa.apk"|ConvertTo-Json|Set-Content "$dir/honda-hash.json"
 $java='C:/Program Files/Eclipse Adoptium/jdk-17.0.20.101-hotspot/bin/java.exe';& $java -jar 'C:/Program Files (x86)/Android/android-sdk/build-tools/32.0.0/lib/apksigner.jar' verify --min-sdk-version 22 --max-sdk-version 22 --print-certs "$dir/factory-aa.apk" *> "$dir/honda-signer.txt";if($LASTEXITCODE-ne0){throw 'Local pulled factory signer verification failed'}
 (Adb -Arguments @('logcat','-d','-v','threadtime'))|Set-Content "$dir/logcat.txt"
}
switch($Stage){
 'INSTALL'{if($state.phase-ne'PREPARED'){throw 'INSTALL requires PREPARED'};if((Adb -Arguments @('shell','pm','list','packages',$package))-match('(?m)^package:'+[regex]::Escape($package)+'\s*$')){throw 'M5 already installed; preserve prior evidence before proceeding'};Snapshot 'before';$factoryHash=Get-Content "$SessionDirectory/before/honda-hash.json" -Raw|ConvertFrom-Json;if($factoryHash.Hash-ne'F9E976F44853C9DB7C8FF5A8610C10CAF1E0B4D1E5BE0886F4F52505C5348146'){throw 'Factory AA differs from last live evidence; stop before install'};[void](Adb -Arguments @('install',$preflight.apk));$state.phase='INSTALLED';$state.liveExecuted=$true;Save;$installedDump=Adb -Arguments @('shell','dumpsys','package',$package);$installedDump|Set-Content "$SessionDirectory/m5-installed-package.txt";$uidMatch=[regex]::Match($installedDump,'userId=(\d+)');if(-not$uidMatch.Success-or[int]$uidMatch.Groups[1].Value-lt10000){throw 'Ordinary UID not verified; no ARM permitted'};if($installedDump-notmatch'versionName=0\.2\.0-m5-single-port-300s'-or$installedDump-notmatch'\bversionCode=3\b'){throw 'Installed version not verified'};Write-Output 'Installed ONLY frozen M5. Prepare all physical steps before separate ARM command.'}
 'ARM'{if($state.phase-ne'INSTALLED'){throw 'Only one ARM allowed after fresh install'};$state|Add-Member -Force NoteProperty armedAt ([DateTime]::UtcNow.ToString('o'));$state|Add-Member -Force NoteProperty deadlineUTC ([DateTime]::UtcNow.AddSeconds(300).ToString('o'));$state.phase='ARM_ATTEMPTED';Save
  (Adb -Arguments @('shell','am','startservice','-n',$preflight.service,'-a','REQUEST_ONCE_AFTER_M4_PASS','--ez','m4_pass_confirmed','true','--ez','wait_for_target','true','--ei','vendor_id','6353','--ei','product_id','11521','--es','run_id',$state.runId))|Set-Content "$SessionDirectory/arm-response.txt"
  $logs=Adb -Arguments @('logcat','-d','-v','threadtime','-s','RDX.M5:I','*:S');$logs|Set-Content "$SessionDirectory/armed-logcat.txt";if($logs-notmatch([regex]::Escape('run='+$state.runId)+'.*event=ARMED')){throw 'ARM not confirmed. Do not swap; inspect evidence. No automatic retry.'};$domains=Adb -Arguments @('shell','ps','-Z');$domains|Set-Content "$SessionDirectory/armed-selinux-processes.txt";$ours=@($domains-split'\r?\n'|Where-Object {$_-match'com\.rdx\.fullscreen\.m5permission\s*$'});if(-not$ours.Count-or($ours-join"`n")-notmatch'u:r:untrusted_app:s0'){throw 'Untrusted app process not verified; do not swap; preserve/retrieve bounded result'};$state.phase='PHONE_SWAP_WAIT_RECONNECT';Save
  Write-Output "Deadline $($state.deadlineUTC). SWAP TO PHONE NOW — WATCH THE RDX SCREEN FOR A USB PERMISSION DIALOG";Write-Output 'No more ADB commands from this script. Manually ALLOW only this app if prompted; do not select a default handler. Reconnect laptop after60–90seconds. If still waiting, allow300-second bound to finish before RETRIEVE.'}
 'RETRIEVE'{if($state.phase-notin@('PHONE_SWAP_WAIT_RECONNECT','ARM_ATTEMPTED')){throw 'RETRIEVE requires an arm attempt; never rerun permission automatically'}
  (Adb -Arguments @('logcat','-d','-v','threadtime'))|Set-Content (Join-Path $SessionDirectory ('reconnect-before-dump-'+(Get-Date -Format 'yyyyMMdd-HHmmss-fff')+'.txt'));
  $logs=Adb -Arguments @('logcat','-d','-v','threadtime','-s','RDX.M5:I','*:S');$logs|Set-Content "$SessionDirectory/m5-before-dump.txt"
  if([DateTime]::UtcNow-lt[DateTime]::Parse($state.deadlineUTC).ToUniversalTime().AddSeconds(3)-and$logs-notmatch([regex]::Escape('run='+$state.runId)+'.*(state=(GRANTED|DENIED|DETACHED|TIMED_OUT|ERROR|CALLBACK_INCONSISTENT)|SERVICE_END)')){throw 'M5 may still be active. Keep laptop connected; wait for bounded deadline, then repeat RETRIEVE only.'}
  [void](Adb -Arguments @('shell','am','startservice','-n',$preflight.service,'-a','DUMP_RESULTS','--es','run_id',$state.runId));$logs=Adb -Arguments @('logcat','-d','-v','threadtime');$logs|Set-Content "$SessionDirectory/reconnect-logcat.txt"
  $converted=(& "$root/scripts/Convert-RdxM5Dump.ps1" -LogFile "$SessionDirectory/reconnect-logcat.txt" -RunId $state.runId -OutputDirectory "$SessionDirectory/reconstructed"|ConvertFrom-Json);$state|Add-Member -Force NoteProperty journal $converted.file
  Get-ChildItem $SessionDirectory -Recurse -File|Get-FileHash|ConvertTo-Json|Set-Content "$SessionDirectory/evidence-before-uninstall.json";$state.phase='RETRIEVED';Save;Write-Output 'Durable journal reconstructed with length/token/SHA256 verification. No raw callback nonce was stored by frozen APK.'}
 'VERIFY'{if($state.phase-ne'RETRIEVED'){throw 'Retrieve exact durable evidence first'};& "$PSScriptRoot/Get-M5JournalVerdict.ps1" -Journal $state.journal -Output "$SessionDirectory/m5-verdict.json";$state.phase='VERIFIED';Save;Write-Output 'LIVE EXPERIMENT COMPLETE. No M6 action permitted. Continue cleanup only.'}
 'UNINSTALL'{if($state.phase-notin@('INSTALLED','RETRIEVED','VERIFIED')){throw 'Retrieve and hash evidence before uninstall; never discard failed evidence automatically'};[void](Adb -Arguments @('shell','am','stopservice','-n',$preflight.service));[void](Adb -Arguments @('uninstall',$package));$remaining=(Adb -Arguments @('shell','pm','list','packages',$package))-match('(?m)^package:'+[regex]::Escape($package)+'\s*$');$ps=Adb -Arguments @('shell','ps');if($remaining-or$ps-match'\bcom\.rdx\.fullscreen\.m5permission\s*(\n|$)'){throw 'M5 package/process cleanup not verified'};[ordered]@{packageAbsent=$true;processAbsent=$true;codeData='Normal successful uninstall guarantee; no privileged private-directory equality claim'}|ConvertTo-Json|Set-Content "$SessionDirectory/cleanup.json";$state.phase='UNINSTALLED';Save}
 'POSTCHECK'{if($state.phase-ne'UNINSTALLED'){throw 'Postcheck follows M5-only uninstall'};Snapshot 'after';$before=Get-Content "$SessionDirectory/before/honda-hash.json" -Raw|ConvertFrom-Json;$after=Get-Content "$SessionDirectory/after/honda-hash.json" -Raw|ConvertFrom-Json;$hashSame=$before.Hash-eq$after.Hash;$geometrySame=(Get-Content "$SessionDirectory/before/wm-size.txt" -Raw)-eq(Get-Content "$SessionDirectory/after/wm-size.txt" -Raw);$signerSame=(Get-Content "$SessionDirectory/before/honda-signer.txt" -Raw)-eq(Get-Content "$SessionDirectory/after/honda-signer.txt" -Raw)
  [ordered]@{factoryAPKHashSame=$hashSame;factorySignerSame=$signerSame;wmSizeSame=$geometrySame;displayWindowDumps='Saved both; manually compare stable geometry, not transient focus/private-data';privateDataEquality='NOT CLAIMED';next='STOP. M6 requires M5 PASS plus separate authorization'}|ConvertTo-Json|Set-Content "$SessionDirectory/postcheck.json";$state.phase='FINISHED';Save;if(-not$hashSame-or-not$signerSame-or-not$geometrySame){throw 'Preservation mismatch: retain evidence and investigate; do not restore/mutate private state'};Write-Output 'M5 cleanup/postcheck complete. STOP; no next milestone executed.'}
}
